.box {
  transition: all 0.3s ease;
  transition: opacity 0.5s linear;
}

@keyframes slide {
  from { left: 0; }
  to { left: 200px; }
}
.box { position: relative; animation: slide 1s infinite; }

function animate() {
  const width = element.offsetWidth; // read
  element.style.width = width + 1 + 'px'; // write
  // CSS: transition: none; animation done via JS
  requestAnimationFrame(animate);
}

.grid {
  display: flex;
  flex-wrap: wrap;
